import random,itertools,heapq
def _brute(n,E,s,t,k):
    best={}
    for u,v,w in E:
        if (u,v) not in best or w<best[(u,v)]: best[(u,v)]=w
    adj={}
    for (u,v),w in best.items(): adj.setdefault(u,[]).append((v,w))
    out=[]
    def dfs(u,path,cost):
        if u==t: out.append((cost,list(path))); return
        for v,w in adj.get(u,[]):
            if v not in path: path.append(v); dfs(v,path,cost+w); path.pop()
    dfs(s,[s],0); out.sort(); return out[:k]
